#!/usr/bin/env node

import { readFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

// Configuration (editable)
const THRESHOLD = 20; // 20% - switch to AG model when any candidate >= this
const FALLBACK_MODEL = 'google/gemini-3-flash-preview';
const AG_PREFIX = 'google-antigravity/';

// Expected marker strings for validation
const MARKER_STATUS_ALPHA_2025 = 'MARKER_STATUS_ALPHA_2025';
const MARKER_JSON_BETA_2025 = 'MARKER_JSON_BETA_2025';

// Anti-Gravity model candidates
const CANDIDATES = [
  'google-antigravity/claude-opus-4-5-thinking',
  'google-antigravity/claude-sonnet-4-5',
  'google-antigravity/claude-sonnet-4-5-thinking',
  'google-antigravity/gemini-3-flash',
  'google-antigravity/gemini-3-pro-high',
  'google-antigravity/gemini-3-pro-low',
  'google-antigravity/gpt-oss-120b-medium'
];

// Get script directory for finding status files
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

function readStatusFile(filename) {
  try {
    return readFileSync(join(__dirname, filename), 'utf8').trim();
  } catch (e) {
    return null;
  }
}

function parseStatusText(statusText) {
  const usageMap = {};

  // Initialize Gemini models with 100% (infinite quota unless specified otherwise)
  for (const cand of CANDIDATES) {
    if (cand.includes('gemini')) {
      usageMap[cand] = 100;
    }
  }

  const lines = statusText.split('\n');
  for (const line of lines) {
    if (line.includes('google-antigravity usage:')) {
      continue; // Skip header line
    }

    // Match lines like "  claude-opus-4-5-thinking 18% left"
    const regex = /^(\s*)([a-zA-Z0-9-.]+)\s+(\d+)%\s+left\s*$/;
    const match = line.match(regex);
    if (match) {
      let modelName = match[2];
      const percent = parseInt(match[3], 10);

      // Add prefix if missing
      if (!modelName.startsWith(AG_PREFIX)) {
        modelName = AG_PREFIX + modelName;
      }
      usageMap[modelName] = percent;
    }
  }

  return usageMap;
}

function parseStatusJson(statusJson) {
  try {
    const parsed = JSON.parse(statusJson);
    // Verify marker
    if (parsed.marker !== MARKER_JSON_BETA_2025) {
      console.warn(`[ModelGuard] Warning: Expected marker ${MARKER_JSON_BETA_2025}, got: ${parsed.marker || 'none'}`);
    }
    return {
      currentModel: parsed.defaults?.model?.primary || '',
      marker: parsed.marker || ''
    };
  } catch (e) {
    return { currentModel: '', marker: '' };
  }
}

function selectBestModel(usageMap, threshold) {
  let bestModel = null;
  let maxPercent = -1;

  for (const model of CANDIDATES) {
    const p = usageMap[model] !== undefined ? usageMap[model] : 0;
    if (p > maxPercent) {
      maxPercent = p;
      bestModel = model;
    }
  }

  return { bestModel, maxPercent };
}

function main() {
