  console.log(`[ModelGuard] Threshold: ${THRESHOLD}%, Fallback: ${FALLBACK_MODEL}`);

  // Read status files
  const statusText = readStatusFile('status.txt');
  const statusJson = readStatusFile('status.json');

  if (!statusText) {
    console.error('[ModelGuard] Error: Could not read status.txt');
    process.exit(1);
  }

  // Verify text marker
  if (!statusText.includes(MARKER_STATUS_ALPHA_2025)) {
    console.warn(`[ModelGuard] Warning: Expected marker ${MARKER_STATUS_ALPHA_2025} not found in status.txt`);
  }

  // Parse current model from JSON
