  // Parse quota percentages
  const usageMap = parseStatusText(statusText);

  console.log('[ModelGuard] Quota status:');
  for (const model of CANDIDATES) {
    const quota = usageMap[model] ?? 0;
    console.log(`  ${model}: ${quota}%`);
  }

  // Find best model
  const { bestModel, maxPercent } = selectBestModel(usageMap, THRESHOLD);

  console.log(`[ModelGuard] Best candidate: ${bestModel} (${maxPercent}%)`);

  // Decision logic
  if (bestModel && maxPercent >= THRESHOLD) {
    // At least one AG model meets threshold - switch to highest quota
    if (currentModel !== bestModel) {
      console.log(`[ModelGuard] Switching to rich model: ${bestModel} (${maxPercent}%)`);
      // In production: run(`openclaw models set ${bestModel}`);
